import * as pulumi from "@pulumi/pulumi";
import * as gcp from "@pulumi/gcp";

/**
 * A Secret Manager secret with secure defaults (automatic replication). This declares only the
 * container; the value is set out of band (Secret Manager UI / `gcloud secrets versions add`) and
 * never lives in git. Use {@link Secret.grant} to let a member read the value.
 */
export class Secret extends gcp.secretmanager.Secret {
  constructor(
    private readonly id: string,
    opts?: pulumi.CustomResourceOptions,
  ) {
    super(id, { secretId: id, replication: { auto: {} } }, opts);
  }

  /** Grants a member (e.g. `serviceAccount:foo@…`) permission to read this secret's value. */
  grant(member: pulumi.Input<string>): gcp.secretmanager.SecretIamMember {
    return new gcp.secretmanager.SecretIamMember(`secret-accessor-${this.id}`, {
      secretId: this.secretId,
      project: this.project,
      role: "roles/secretmanager.secretAccessor",
      member,
    });
  }
}

import * as pulumi from "@pulumi/pulumi";
import * as gcp from "@pulumi/gcp";

/** A GCP service account with a convenient IAM `member` string and impersonation helpers. */
export class ServiceAccount extends gcp.serviceaccount.Account {
  constructor(accountId: string, displayName: string, opts?: pulumi.CustomResourceOptions) {
    super(accountId, { accountId, displayName }, opts);
  }

  /** The IAM member string for this service account, e.g. `serviceAccount:foo@…`. */
  get member(): pulumi.Output<string> {
    return pulumi.interpolate`serviceAccount:${this.email}`;
  }

  /**
   * Lets the given members run operations as, and mint tokens for (impersonate), this service
   * account.
   */
  allowImpersonation(members: string[]): void {
    for (const member of members) {
      new gcp.serviceaccount.IAMMember(`${member}-user`, {
        serviceAccountId: this.name,
        role: "roles/iam.serviceAccountUser",
        member,
      });

      new gcp.serviceaccount.IAMMember(`${member}-impersonator`, {
        serviceAccountId: this.name,
        role: "roles/iam.serviceAccountTokenCreator",
        member,
      });
    }
  }
}

